package dev.carevisit.core

import java.time.*
import kotlin.test.*

class MachineTest {
    private val start = Instant.parse("2026-11-15T01:00:00Z").toEpochMilli()
    private fun machine(consent: Boolean = true, family: Boolean = false) = VisitMachine(Archive(consent = Consent(if(consent) start else null, if(family) start else null)), start)
    private fun begin(m: VisitMachine): List<Effect> {
        m.handle(Event.Manual(Hospital("○○병원")),start,0)
        m.handle(Event.Vehicle(Gear.D,12.0,true,false),start,0)
        return m.handle(Event.Tick,start+60_000,60_000)
    }
    private fun answer(m: VisitMachine, s: String?, at: Long = start+60_000): List<Effect> = m.handle(Event.Answer(m.archive.session.prompt!!.id,s),at,at-start)
    private fun pre(m: VisitMachine) { begin(m); answer(m,"네"); repeat(5) { answer(m, "넘어가") } }
    @Test fun consentBeforeInterviewOrRecording() { val m=machine(false); begin(m); assertEquals(AskKind.HEALTH,m.archive.session.prompt?.kind); answer(m,"무릎 아파"); assertTrue(m.archive.session.visit!!.utterances.isEmpty()); answer(m,"아니"); assertNull(m.archive.consent.healthAt); assertTrue(m.archive.session.visit!!.utterances.isEmpty()) }
    @Test fun spokenConsentTimeThenOffer() { val m=machine(false); begin(m); answer(m,"네"); assertEquals(start+60_000,m.archive.consent.healthAt); assertEquals(AskKind.PRE_OFFER,m.archive.session.prompt?.kind) }
    @Test fun safeTimeOnlyCountsDriving() { val m=machine(); m.handle(Event.Manual(Hospital("○○병원")),start,0); m.handle(Event.Vehicle(Gear.P,0.0,false,false),start,0); m.handle(Event.Tick,start+120_000,120_000); assertNull(m.archive.session.prompt); m.handle(Event.Vehicle(Gear.D,10.0,true,false),start+120_000,120_000); m.handle(Event.Tick,start+179_999,179_999); assertNull(m.archive.session.prompt); m.handle(Event.Tick,start+180_000,180_000); assertNotNull(m.archive.session.prompt) }
    @Test fun destinationAndSavedDetection() { val m=machine(); m.handle(Event.Destination(Hospital("공원")),start,0); assertEquals(Phase.IDLE,m.archive.session.phase); m.handle(Event.Destination(Hospital("○○치과")),start,0); assertEquals(Phase.WAIT_SAFE,m.archive.session.phase) }
    @Test fun oneReaskThenSkip() { val m=machine(); begin(m); answer(m,"응"); answer(m,null); assertEquals(1,m.archive.session.prompt?.retry); answer(m,null); assertEquals(Slot.DURATION,m.archive.session.prompt?.slot) }
    @Test fun allSlotsTraceable() { val m=machine(); begin(m); answer(m,"응"); answer(m,"무릎이 아프"); answer(m,"사흘전부터"); answer(m,"계단오를때"); answer(m,"기존 약 먹어"); answer(m,"걸어도 돼요"); answer(m,"아니"); val v=m.archive.session.visit!!; assertTrue(v.traceable()); assertEquals("P3D",v.slots[Slot.DURATION]!!.first().normalized); assertTrue(Templates.memo(v).contains("걸어도 돼요")) }
    @Test fun questionsLimitedToFive() { val m=machine(); begin(m); answer(m,"응"); repeat(4){answer(m,"넘어가")}; repeat(5){ answer(m,"질문 $it"); if(it<4) answer(m,"또있어") }; assertEquals(5,m.archive.session.visit!!.slots[Slot.QUESTION]!!.size); assertEquals(Phase.MEMO,m.archive.session.phase) }
    @Test fun staleAnswerIgnored() { val m=machine(); begin(m); val old=m.archive.session.prompt!!.id; answer(m,"네"); m.handle(Event.Answer(old,"무릎"),start,0); assertTrue(m.archive.session.visit!!.utterances.isEmpty()) }
    @Test fun healthConsentTouchCannotAnswerWhileMoving() { val m=machine(false); begin(m); m.handle(Event.Answer(m.archive.session.prompt!!.id,"응",true),start,0); assertEquals(AskKind.HEALTH,m.archive.session.prompt?.kind) }
    @Test fun alarmIsFixedAndNoAssessment() { val m=machine(); begin(m); answer(m,"응"); val effects=answer(m,"가슴이 아파"); assertTrue(effects.any { it is Effect.Say && it.text == Policy.DISCOMFORT_LINE }); assertEquals("가슴이 아파",m.archive.session.visit!!.text(Slot.SYMPTOM)) }
    @Test fun emergencyDoesNotFillSlot() { val m=machine(); begin(m); answer(m,"응"); val e=answer(m,"119"); assertTrue(e.any { it is Effect.Say && it.text==Policy.EMERGENCY_LINE }); assertTrue(m.archive.session.visit!!.utterances.isEmpty()) }
    @Test fun arrivalRequiresParkDoorAndFamilyLineIsConditional() { val m=machine(); pre(m); m.handle(Event.Arrived,start,0); var e=m.handle(Event.Vehicle(Gear.D,0.0,true,true),start,0); assertFalse(e.any { it is Effect.Say }); e=m.handle(Event.Vehicle(Gear.P,0.0,false,true),start,0); assertTrue(e.any { it is Effect.Say && it.text=="천천히 내리세요." }); assertTrue(m.archive.session.droppedOff) }
    @Test fun noPostBeforeFifteenMinutes() { val m=machine(); pre(m); m.handle(Event.Arrived,start,0); m.handle(Event.Vehicle(Gear.P,0.0,false,false),start,0); m.handle(Event.Vehicle(Gear.D,0.0,true,false),start+899_999,899_999); assertNull(m.archive.session.prompt); m.handle(Event.Vehicle(Gear.P,0.0,false,false),start+900_000,900_000); m.handle(Event.Vehicle(Gear.D,0.0,true,false),start+900_001,900_001); assertEquals(AskKind.POST_OFFER,m.archive.session.prompt?.kind) }
    @Test fun familyReplyOnlyInParkingMode() { val m=machine(family=true); pre(m); m.handle(Event.Arrived,start,0); m.handle(Event.Vehicle(Gear.P,0.0,false,false),start,0); m.handle(Event.ParkingMode,start,0); val e=m.handle(Event.FamilyReply("r1","나왔어"),start,0); assertTrue(e.any { it is Effect.Say && "정문에 나오셨대요" in it.text }); assertTrue(m.handle(Event.FamilyReply("r1","나왔어"),start,0).isEmpty()) }
    @Test fun withdrawalErasesAndPreventsLateAnswers() { val m=machine(); begin(m); answer(m,"응"); val id=m.archive.session.prompt!!.id; answer(m,"무릎 아파"); m.handle(Event.Withdraw,start,0); m.handle(Event.Answer(id,"사흘"),start,0); assertNull(m.archive.consent.healthAt); assertTrue(m.archive.visits.isEmpty()); assertNull(m.archive.session.visit) }
    @Test fun shareNeedsBothConsentsAndIndividualYes() { val m=machine(family=true); pre(m); m.handle(Event.Vehicle(Gear.P,0.0,false,false),start,0); val ask=m.handle(Event.ShareMemo,start,0); assertTrue(ask.any { it is Effect.Ask }); assertFalse(ask.any { it is Effect.Send }); assertTrue(answer(m,"응").any { it is Effect.Send }); val n=machine(); pre(n); assertTrue(n.handle(Event.ShareMemo,start,0).isEmpty()) }
    @Test fun noAutomaticResendAfterRestart() { val m=machine(family=true); pre(m); m.handle(Event.Vehicle(Gear.P,0.0,false,false),start,0); m.handle(Event.ShareMemo,start,0); val restored=VisitMachine(m.archive,start); val e=restored.handle(Event.Boot,start,0); assertFalse(e.any { it is Effect.Send }); assertEquals(Phase.RECOVERY,restored.archive.session.phase) }
    @Test fun restartResumeAndAbandon() { val m=machine(); begin(m); answer(m,"네"); answer(m,"무릎"); val resumed=VisitMachine(m.archive,start); resumed.handle(Event.Boot,start,0); resumed.handle(Event.Vehicle(Gear.P,0.0,false,false),start,0); resumed.handle(Event.Resume,start,0); assertEquals(Slot.DURATION,resumed.archive.session.prompt?.slot); assertTrue(resumed.archive.session.visit!!.traceable()); val abandoned=VisitMachine(m.archive,start); abandoned.handle(Event.Boot,start,0); abandoned.handle(Event.Vehicle(Gear.P,0.0,false,false),start,0); abandoned.handle(Event.Abandon,start,0); assertNull(abandoned.archive.session.visit) }
    @Test fun retentionBoundaryAndDeleteAll() { val v=Visit("v",Hospital("○○병원"),start-180L*86_400_000); val a=Archive(consent=Consent(start),visits=listOf(v)); assertTrue(Policy.purge(a,start).visits.isEmpty()); val m=VisitMachine(a,start); m.handle(Event.DeleteAll,start,0); assertNull(m.archive.consent.healthAt); assertTrue(m.archive.visits.isEmpty()) }
    @Test fun continuityUsesOriginalWords() { val u=Utterance("u","다음에 무릎 확인",start-1000); val v=Visit("v",Hospital("○○병원"),start-1000,listOf(u),mapOf(Slot.NEXT_CHECK to listOf(SlotValue("u",u.text))),complete=true); val m=VisitMachine(Archive(consent=Consent(start),visits=listOf(v)),start); begin(m); answer(m,"네"); assertEquals(Slot.CONTINUITY,m.archive.session.prompt?.slot); assertTrue(m.archive.session.prompt!!.text.contains(u.text)) }
}
